import { NextRequest, NextResponse } from 'next/server';
import * as XLSX from 'xlsx';
import { adminClient } from '@/lib/supabase';
import { ensureRouteAdmin } from '@/lib/route-auth';
import { nameSchema, rollSchema } from '@/utils/validation';
export async function POST(req: NextRequest) { const unauthorized = await ensureRouteAdmin(); if (unauthorized) return unauthorized; const form = await req.formData(); const file = form.get('file'); if (!(file instanceof File)) return NextResponse.json({ error: 'Excel file is required' }, { status: 400 }); const wb = XLSX.read(await file.arrayBuffer()); const rows = XLSX.utils.sheet_to_json<Record<string, unknown>>(wb.Sheets[wb.SheetNames[0]], { defval: '' }); const seen = new Set<string>(); const records = []; for (const [i, row] of rows.entries()) { const roll = rollSchema.safeParse(String(row['Roll Number'] ?? row.roll_number ?? '')); const name = nameSchema.safeParse(String(row.Name ?? row.name ?? '')); if (!roll.success || !name.success) return NextResponse.json({ error: `Invalid data on row ${i + 2}` }, { status: 400 }); if (seen.has(roll.data)) return NextResponse.json({ error: `Duplicate roll number in file: ${roll.data}` }, { status: 400 }); seen.add(roll.data); records.push({ roll_number: roll.data, name: name.data }); } const { error } = await adminClient().from('participants').upsert(records, { onConflict: 'roll_number' }); if (error) return NextResponse.json({ error: error.message }, { status: 500 }); return NextResponse.json({ insertedOrUpdated: records.length }); }
